//! Typed public podcast discovery/feed/playback. Stream URLs remain host-owned.
use crate::Result;use serde_json::Value;
fn text(v:&Value,max:usize)->bool{v.as_str().is_some_and(|s|s.chars().count()<=max&&!s.chars().any(char::is_control))}
fn feed(v:&Value)->bool{text(v,2048)&&v.as_str().is_some_and(|s|crate::sdk_http::origin(s).is_ok())}
pub(crate) fn episode(v:&Value)->bool{v.as_str().is_some_and(|s|s.len()==64&&s.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b)))}
pub(crate) fn request(service:&str,args:&Value)->Result<()>{let a=args.as_object().ok_or("Use podcast arguments")?;let allowed=match service{"podcasts.search"=>vec!["query","language","offset"],"podcasts.feed"=>vec!["feed","offset"],"podcasts.play"|"podcasts.download"|"podcasts.delete"=>vec!["feed","episode"],"podcasts.downloads"=>vec![],_=>return Err("Unsupported podcast service".into())};if a.keys().any(|k|!allowed.contains(&k.as_str())){return Err("Unsupported podcast argument".into())}if service=="podcasts.downloads"{return Ok(())}if service=="podcasts.search"{for(k,n)in[("query",80),("language",16)]{if a.get(k).is_some_and(|v|!text(v,n)){return Err("Invalid podcast filter".into())}}}else if !feed(&args["feed"]){return Err("Use a public HTTPS podcast feed".into())}if matches!(service,"podcasts.play"|"podcasts.download"|"podcasts.delete"){if !episode(&args["episode"]){return Err("Choose an episode from its feed".into())}}else if a.get("offset").is_some_and(|v|v.as_u64().is_none_or(|n|n>1_000_000||n%20!=0)){return Err("Invalid podcast page".into())}Ok(())}
pub(crate) fn reply(service:&str,v:&Value)->Result<()>{if v.to_string().len()>65536{return Err("Podcast response too large".into())}if matches!(service,"podcasts.download"|"podcasts.delete"|"podcasts.downloads"){let rows=v["downloads"].as_array().filter(|r|r.len()<=500).ok_or("Invalid downloads")?;if rows.iter().any(|r|!episode(r)){return Err("Invalid downloaded episode".into())}return Ok(())}if service=="podcasts.play"{crate::sdk_tasks::reply("media.status",&v["player"])?;if !episode(&v["episode"]["id"]){return Err("Invalid selected episode".into())}}else{let rows=v["items"].as_array().filter(|a|a.len()<=20).ok_or("Invalid podcast page")?;for row in rows{if !text(&row["title"],200)||row["title"].as_str()==Some(""){return Err("Invalid podcast title".into())}if service=="podcasts.search"{if !feed(&row["feed"]){return Err("Invalid directory feed".into())}}else if !episode(&row["id"]){return Err("Invalid episode ID".into())}}}Ok(())}
#[cfg(test)]mod tests{use super::*;use serde_json::json;
#[test]fn podcast_library_does_not_accept_credentials_or_guest_stream_urls(){for v in[json!({"feed":"http://example.org/rss","episode":"a".repeat(64)}),json!({"feed":"https://u:p@example.org/rss","episode":"a".repeat(64)}),json!({"feed":"https://example.org/rss","episode":"a".repeat(64),"url":"https://elsewhere.org/audio"})]{assert!(request("podcasts.play",&v).is_err())}request("podcasts.play",&json!({"feed":"https://example.org/rss","episode":"a".repeat(64)})).unwrap();assert!(request("podcasts.search",&json!({"query":"x".repeat(81)})).is_err())}
#[test]fn podcast_pages_are_bounded_not_a_listening_quota(){request("podcasts.search",&json!({"offset":1000000})).unwrap();assert!(reply("podcasts.feed",&json!({"items":[{"title":"x","id":"bad"}]})).is_err());}
}
